class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        dp = [1]                     # one element placed
        for ch in s:
            nxt_len = len(dp) + 1
            nxt = [0] * nxt_len
            # prefix sums of dp
            pre = [0] * (len(dp) + 1)
            for i in range(len(dp)):
                pre[i+1] = (pre[i] + dp[i]) % MOD
            if ch == 'I':
                for j in range(nxt_len):
                    nxt[j] = pre[j]          # sum of dp[0..j-1]
            else:  # 'D'
                total = pre[len(dp)]
                for j in range(nxt_len):
                    nxt[j] = (total - pre[j]) % MOD
            dp = nxt
        return sum(dp) % MOD

