from typing import List
from functools import lru_cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # Each topping can be used at most twice.
        toppingCosts = toppingCosts * 2

        @lru_cache(None)
        def dp(i: int, remain: int) -> int:
            # No more toppings or remaining <= 0 → take nothing.
            if i >= len(toppingCosts) or remain <= 0:
                return 0
            # Skip current topping.
            skip = dp(i + 1, remain)
            # Take current topping.
            take = toppingCosts[i] + dp(i + 1, remain - toppingCosts[i])
            # Choose the one with smaller distance to remain; break ties by smaller sum.
            return min(skip, take, key=lambda y: (abs(y - remain), y))

        best = float('inf')
        for b in baseCosts:
            total = b + dp(0, target - b)
            # Keep the result closest to target, preferring smaller total on a tie.
            best = min(best, total, key=lambda x: (abs(x - target), x))
        return best

