from typing import List

class Solution:
    def findTheString(self, lcp: List[List[int]]) -> str:
        n = len(lcp)
        if n == 0:
            return ''

        # basic validation
        for i in range(n):
            if lcp[i][i] != n - i:
                return ''
            for j in range(i + 1, n):
                if lcp[i][j] != lcp[j][i]:
                    return ''
                if lcp[i][j] > n - max(i, j):
                    return ''

        # construct character assignment
        pattern = [None] * n
        next_char = 0
        for i in range(n):
            if pattern[i] is not None:
                continue
            # assign a new character
            pattern[i] = next_char
            next_char += 1
            # propagate to positions with positive LCP
            for j in range(i + 1, n):
                if lcp[i][j] > 0:
                    if pattern[j] is None:
                        pattern[j] = pattern[i]
                    elif pattern[j] != pattern[i]:
                        return ''

        # fill any remaining unassigned positions (LCP all zeros with previous)
        for i in range(n):
            if pattern[i] is None:
                pattern[i] = next_char
                next_char += 1

        # verify we didn't exceed 26 distinct letters
        if max(pattern) > 25:
            return ''

        # compute LCP of the constructed pattern
        pattern_lcp = [[0] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                if pattern[i] == pattern[j]:
                    if i + 1 < n and j + 1 < n:
                        pattern_lcp[i][j] = pattern_lcp[i + 1][j + 1] + 1
                    else:
                        pattern_lcp[i][j] = 1
                else:
                    pattern_lcp[i][j] = 0

        # compare with given LCP
        for i in range(n):
            for j in range(n):
                if lcp[i][j] != pattern_lcp[i][j]:
                    return ''

        # translate to letters
        return ''.join(chr(ord('a') + c) for c in pattern)

