from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build a trie for all forbidden strings
        trie = {}
        for f in forbidden:
            t = trie
            for c in f:
                if c not in t:
                    t[c] = {}
                t = t[c]
            t["end"] = True

        # Returns the length of the earliest forbidden word found in s, or 0 if none.
        def isForbidden(s: str) -> int:
            t = trie
            cnt = 0
            for c in s:
                if c not in t:
                    # not a prefix of any forbidden word
                    return 0
                t = t[c]
                cnt += 1
                if "end" in t:
                    # found a forbidden word ending here
                    return cnt
            return 0

        res = 0
        j = len(word)  # exclusive end of the current valid window
        for i in range(len(word) - 1, -1, -1):
            found = isForbidden(word[i:j])
            if found:
                # shrink the window to just before the forbidden's end
                j = i + found - 1
            res = max(res, j - i)
        return res

class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if n1 == 0:
            return 0
        # quick check: all characters of s2 must appear in s1
        set_s1 = set(s1)
        for ch in s2:
            if ch not in set_s1:
                return 0
        # keep only characters that appear in s2
        s1 = ''.join([c for c in s1 if c in set(s2)])
        if not s1:
            return 0

        # use a dict to detect cycles based on position in s2 after each s1 block
        memo = {}
        idx_s1 = 0
        idx_s2 = 0
        s2_repeat = 0
        blocks = 0

        while blocks < n1:
            # process one character of the current s1 block
            if s1[idx_s1] == s2[idx_s2]:
                idx_s2 += 1
                if idx_s2 == len(s2):
                    s2_repeat += 1
                    idx_s2 = 0
            idx_s1 += 1
            if idx_s1 == len(s1):
                # finished a block of s1
                idx_s1 = 0
                blocks += 1
                if idx_s2 in memo:
                    prev_blocks, prev_repeat = memo[idx_s2]
                    cycle_blocks = blocks - prev_blocks
                    cycle_repeats = s2_repeat - prev_repeat
                    # skip full cycles
                    remain = n1 - prev_blocks
                    full = remain // cycle_blocks
                    s2_repeat = prev_repeat + full * cycle_repeats
                    # simulate the remaining blocks
                    rest = remain % cycle_blocks
                    for _ in range(rest):
                        for ch in s1:
                            if ch == s2[idx_s2]:
                                idx_s2 += 1
                                if idx_s2 == len(s2):
                                    s2_repeat += 1
                                    idx_s2 = 0
                    return s2_repeat // n2
                else:
                    memo[idx_s2] = (blocks, s2_repeat)
        return s2_repeat // n2

