from functools import cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        toppingCosts *= 2

        @cache
        def fn(i: int, x: int) -> int:
            """Return sum of a subsequence of toppingCosts[i:] closest to x."""
            if x < 0 or i == len(toppingCosts):
                return 0
            # skip this topping
            best = fn(i + 1, x)
            # take this topping (and possibly its duplicate later)
            take = toppingCosts[i] + fn(i + 2, x - toppingCosts[i])
            # choose the result closest to x; break ties by smaller sum
            return min(best, take, key=lambda y: (abs(y - x), y))

        ans = float('inf')
        for bc in baseCosts:
            total = bc + fn(0, target - bc)
            # keep the total closest to target, break ties by lower cost
            if abs(total - target) < abs(ans - target) or (abs(total - target) == abs(ans - target) and total < ans):
                ans = total
        return ans

