from typing import List
import bisect

class Solution:
    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:
        window: List[int] = []
        result: List[float] = []
        for i, x in enumerate(nums):
            # insert new element keeping window sorted
            bisect.insort(window, x)
            # remove element that falls out of the window
            if len(window) > k:
                out = nums[i - k]                # element to remove
                idx = bisect.bisect_left(window, out)
                window.pop(idx)
            # when window size equals k, compute median
            if len(window) == k:
                if k % 2 == 1:
                    result.append(float(window[k // 2]))
                else:
                    median = (window[k // 2 - 1] + window[k // 2]) / 2.0
                    result.append(median)
        return result

