class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        dp = [1]                     # dp[j] for length 1, only j=0

        for i, ch in enumerate(s):
            ndp = [0] * (i + 2)      # next length will have i+2 numbers
            if ch == 'I':
                # when current relation is 'I', next number must be larger
                cur = 0
                for j in range(i + 1):
                    cur = (cur + dp[j]) % MOD
                    ndp[j + 1] = cur
            else:  # ch == 'D'
                # when relation is 'D', next number must be smaller or equal
                cur = 0
                for j in range(i, -1, -1):
                    cur = (cur + dp[j]) % MOD
                    ndp[j] = cur
            dp = ndp

        return sum(dp) % MOD

