from typing import List
from functools import cache
import math

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        toppingCosts *= 2  # allow each topping up to twice

        @cache
        def fn(i: int, x: int) -> int:
            """Return sum of a subsequence of toppingCosts[i:] that is closest to x."""
            # Base case: no more toppings or target already non‑positive
            if i == len(toppingCosts) or x <= 0:
                return 0
            # Option 1: skip current topping
            skip = fn(i + 1, x)
            # Option 2: take current topping
            take = toppingCosts[i] + fn(i + 1, x - toppingCosts[i])
            # Choose the one with smallest distance to x (and smaller sum on ties)
            return min(skip, take, key=lambda y: (abs(y - x), y))

        ans = math.inf
        for bc in baseCosts:
            total = bc + fn(0, target - bc)
            # Keep the total closest to target; break ties by smaller cost
            if abs(total - target) < abs(ans - target) or (abs(total - target) == abs(ans - target) and total < ans):
                ans = total
        return ans

