class Solution:
    def findComplement(self, num: int) -> int:
        # Handle the edge case where num is 0
        if num == 0:
            return 1

        complement_bits = ''
        while num > 0:
            # Use == for comparison, not =
            if num % 2 == 1:
                complement_bits += '0'   # bit 1 -> 0
            else:
