class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        # Quick rejection: characters of s2 must appear in s1
        if not set(s2).issubset(set(s1)):
            return 0

        s2_len = len(s2)
        # Map: index in s2 after processing a block of s1 -> (block count, s2 match count)
        rec = {}
        s2_match = 0
        i = 0          # number of s1 blocks processed
        idx_s2 = 0     # next position to match in s2

        while i < n1:
            i += 1
            for ch in s1:
                if ch == s2[idx_s2]:
                    idx_s2 += 1
                    if idx_s2 == s2_len:
                        s2_match += 1
                        idx_s2 = 0

            if idx_s2 not in rec:
                rec[idx_s2] = (i, s2_match)
            else:
                break

        # If we never found a cycle, we processed all n1 blocks
        if i == n1:
            return s2_match // n2

        # Cycle detected
        pre_i, pre_match = rec[idx_s2]
        cycle_i = i - pre_i
        cycle_match = s2_match - pre_match

        remaining_blocks = n1 - pre_i
        full_cycles = remaining_blocks // cycle_i
        s2_match = pre_match + full_cycles * cycle_match

        rest_blocks = remaining_blocks % cycle_i
        for _ in range(rest_blocks):
            for ch in s1:
                if ch == s2[idx_s2]:
                    idx_s2 += 1
                    if idx_s2 == s2_len:
                        s2_match += 1
                        idx_s2 = 0

        return s2_match // n2

