from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build a trie of reversed forbidden strings.
        trie = {}
        max_len = 0
        for f in forbidden:
            rev = f[::-1]
            max_len = max(max_len, len(rev))
            node = trie
            for ch in rev:
                if ch not in node:
                    node[ch] = {}
                node = node[ch]
            node['end'] = True

        n = len(word)
        left = 0
        ans = 0

        for right in range(n):
            node = trie
            # Scan backwards from `right` while staying within the current window.
            # At most `max_len` steps or until we go past `left`.
            for offset in range(max_len):
                pos = right - offset
                if pos < left:
                    break
                ch = word[pos]
                if ch not in node:
                    break
                node = node[ch]
                if 'end' in node:
                    # Found a forbidden substring that ends at `right` and starts at `pos`.
                    left = pos + 1
            # Update answer with the size of the current valid window.
            ans = max(ans, right - left + 1)

        return ans

