from typing import List
import functools

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        self.R = len(pizza)
        self.C = len(pizza[0])
        MOD = 10**9 + 7

        # 2D prefix sum of apples
        self.pre = [[0] * (self.C + 1) for _ in range(self.R + 1)]
        total_apples = 0
        for i in range(self.R):
            for j in range(self.C):
                add = 1 if pizza[i][j] == 'A' else 0
                total_apples += add
                self.pre[i+1][j+1] = (
                    self.pre[i][j+1] + self.pre[i+1][j] - self.pre[i][j] + add
                )

        if total_apples < k:
            return 0
        if k == 1:
            return 1

        @functools.lru_cache(None)
        def dfs(i: int, j: int, pieces: int) -> int:
            # apples in region (i..R-1, j..C-1)
            def region_apples() -> int:
                return (
                    self.pre[self.R][self.C]
                    - self.pre[i][self.C]
                    - self.pre[self.R][j]
                    + self.pre[i][j]
                )

            if pieces == 1:
                return 1 if region_apples() > 0 else 0

            ans = 0

            # horizontal cuts
            for r in range(i, self.R - 1):
                top = (
                    self.pre[r+1][self.C]
                    - self.pre[i][self.C]
                    - self.pre[r+1][j]
                    + self.pre[i][j]
                )
                if top > 0:
                    ans = (ans + dfs(r + 1, j, pieces - 1)) % MOD

            # vertical cuts
            for c in range(j, self.C - 1):
                left = (
                    self.pre[self.R][c+1]
                    - self.pre[i][c+1]
                    - self.pre[self.R][j]
                    + self.pre[i][j]
                )
                if left > 0:
                    ans = (ans + dfs(i, c + 1, pieces - 1)) % MOD

            return ans

        return dfs(0, 0, k - 1) % MOD

