from typing import List
from functools import lru_cache

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        self.r = len(pizza)
        self.c = len(pizza[0])

        # row‑wise and column‑wise prefix sums
        self.pfsum_row = [[0] * self.c for _ in range(self.r)]
        self.pfsum_col = [[0] * self.c for _ in range(self.r)]

        total_apples = 0
        for i in range(self.r):
            row_cnt = 0
            for j in range(self.c):
                if pizza[i][j] == 'A':
                    row_cnt += 1
                    total_apples += 1
                self.pfsum_row[i][j] = row_cnt
                # column prefix: apples in column j from row 0 to i
                if i > 0:
                    self.pfsum_col[i][j] = self.pfsum_col[i-1][j] + row_cnt
                else:
                    self.pfsum_col[i][j] = row_cnt

        if total_apples < k:
            return 0
        if k == 1:
            return 1

        @lru_cache(None)
        def dp(i: int, j: int, pieces: int) -> int:
            # pieces = number of pieces we still need to obtain from sub‑pizza (i,j)
            if pieces == 1:
                # check whether the remaining sub‑pizza contains at least one apple
                for col in range(j, self.c):
                    if (self.pfsum_col[self.r-1][col] -
                        (self.pfsum_col[i-1][col] if i > 0 else 0)) > 0:
                        return 1
                return 0

            ways = 0

            # try every horizontal cut (cut before row r)
            for r in range(i, self.r - 1):
                # top part (i..r, j..c-1) must contain at least one apple
                ok = False
                for col in range(j, self.c):
                    if (self.pfsum_col[r][col] -
                        (self.pfsum_col[i-1][col] if i > 0 else 0)) > 0:
                        ok = True
                        break
                if ok:
                    ways = (ways + dp(r + 1, j, pieces - 1)) % 1000000007

            # try every vertical cut (cut before column c)
            for c in range(j, self.c - 1):
                ok = False
                for row in range(i, self.r):
                    if (self.pfsum_row[row][c] -
                        (self.pfsum_row[row][j-1] if j > 0 else 0)) > 0:
                        ok = True
                        break
                if ok:
                    ways = (ways + dp(i, c + 1, pieces - 1)) % 1000000007

            return ways

        return dp(0, 0, k) % 1000000007

