from functools import lru_cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        toppingCosts = toppingCosts * 2
        n = len(toppingCosts)

        @lru_cache(None)
        def dfs(i: int, x: int) -> int:
            # base case: no more toppings or target already non‑positive
            if x <= 0 or i == n:
                return 0
            # option: skip current topping
            best = dfs(i + 1, x)
            # option: take current topping (one copy; duplication handles second use)
            take = toppingCosts[i] + dfs(i + 1, x - toppingCosts[i])
            # choose whichever is closer to target x
            if abs(take - x) < abs(best - x) or (abs(take - x) == abs(best - x) and take < best):
                best = take
            return best

        ans = float('inf')
        for bc in baseCosts:
            cand = bc + dfs(0, target - bc)
            # compare with current best, using absolute distance and tie‑break on smaller cost
            if abs(cand - target) < abs(ans - target) or (abs(cand - target) == abs(ans - target) and cand < ans):
                ans = cand
        return ans

