class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if n1 == 0:
            return 0
        # quick check: every character of s2 must appear in s1
        set_s1 = set(s1)
        for ch in set(s2):
            if ch not in set_s1:
                return 0

        s2_len = len(s2)
        # recall maps the position in s2 after a whole s1 block to (cnt1, cnt2)
        recall = {}
        cnt1 = cnt2 = 0
        idx2 = 0

        while cnt1 < n1:
            # consume one s1 block
            for ch in s1:
                if ch == s2[idx2]:
                    idx2 += 1
                    if idx2 == s2_len:
                        cnt2 += 1
                        idx2 = 0
            cnt1 += 1

            # cycle detection
            if idx2 in recall:
                prev_cnt1, prev_cnt2 = recall[idx2]
                cycle_s1 = cnt1 - prev_cnt1
                cycle_s2 = cnt2 - prev_cnt2
                remaining = n1 - cnt1
                full = remaining // cycle_s1
                cnt2 += full * cycle_s2
                remaining %= cycle_s1
                # simulate the rest of the blocks
                while remaining:
                    for ch in s1:
                        if ch == s2[idx2]:
                            idx2 += 1
                            if idx2 == s2_len:
                                cnt2 += 1
                                idx2 = 0
                    remaining -= 1
                break
            else:
                recall[idx2] = (cnt1, cnt2)

        return cnt2 // n2

