from typing import List
from functools import lru_cache

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        R = len(pizza)
        C = len(pizza[0])
        # Build 2D prefix sum of apples: pref[i][j] = # apples in rows 0..i-1, cols 0..j-1
        pref = [[0] * (C + 1) for _ in range(R + 1)]
        for i in range(R):
            row_sum = 0
            for j in range(C):
                row_sum += 1 if pizza[i][j] == 'A' else 0
                pref[i+1][j+1] = pref[i][j+1] + row_sum

        def anyApple(r1, c1, r2, c2):
            """Return True if there is at least one apple in rectangle [r1,r2] x [c1,c2] (inclusive)."""
            return pref[r2+1][c2+1] - pref[r1][c2+1] - pref[r2+1][c1] + pref[r1][c1] > 0

        @lru_cache(None)
        def dfs(row, col, cuts):
            if cuts == 1:
                # If the remaining sub‑pizza contains an apple, we can keep it as the last piece.
                return 1 if anyApple(row, col, R-1, C-1) else 0
            total = 0
            # Horizontal cuts: cut after each possible row, leaving at least cuts‑1 rows below.
            for r in range(row, R - cuts + 1):
                if anyApple(row, col, r, C-1):
                    total += dfs(r + 1, col, cuts - 1)
            # Vertical cuts
            for c in range(col, C - cuts + 1):
                if anyApple(row, col, R-1, c):
                    total += dfs(row, c + 1, cuts - 1)
            return total

        return dfs(0, 0, k) % (10**9 + 7)

