class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build trie for forbidden words
        trie = {}
        for f in forbidden:
            t = trie
            for c in f:
                if c not in t:
                    t[c] = {}
                t = t[c]
            t["end"] = True

        # Return length of the longest prefix of s that is a forbidden word
        def isForbidden(s: str):
            t = trie
            counter = 0
            for c in s:
                if c not in t:
                    return False
                t = t[c]
                counter += 1
                if "end" in t:
                    return counter
            return False

        # Scan from right to keep the right bound of a valid substring
        res = 0
        j = len(word)  # exclusive bound
        for i in range(len(word) - 1, -1, -1):
            sub = word[i:j]
            tru = isForbidden(sub)
            if tru:
                # shrink bound to just after the found forbidden prefix
                j = i + tru - 1
            res = max(res, j - i)
        return res

