class Solution:
    def dp(self, i, prev, ct, k, s, n, memo):
        if k < 0:
            return float('inf')
        if i >= n:
            # encode the current run
            if ct > 1:
                return len(str(ct)) + 1
            elif ct == 1:
                return 1
            else:
                return 0
        if (i, prev, ct, k) in memo:
            return memo[(i, prev, ct, k)]
        # keep current character
        if s[i] == prev:
            inc = self.dp(i+1, prev, ct+1, k, s, n, memo)
        else:
            # finish previous run
            x = 0
            if ct > 1:
                x = len(str(ct)) + 1
            elif ct == 1:
                x = 1
            inc = x + self.dp(i+1, s[i], 1, k, s, n, memo)
        # delete current character
        exc = self.dp(i+1, prev, ct, k-1, s, n, memo)
        memo[(i, prev, ct, k)] = min(inc, exc)
        return memo[(i, prev, ct, k)]

    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        n = len(s)
        return self.dp(0, "", 0, k, s, n, {})

