class Solution:
    def validArrangement(self, pairs: List[List[int]]) -> List[List[int]]:
        if not pairs:
            return []

        graph = defaultdict(list)
        degree = defaultdict(int)  # net out-degree (out - in)
        for x, y in pairs:
            graph[x].append(y)
            degree[x] += 1
            degree[y] -= 1

        # Find start node: out-degree - in-degree == 1, otherwise any node with outgoing edges.
        start = None
        for node, d in degree.items():
