from typing import List

class Solution:
    def maxPower(self, stations: List[int], r: int, k: int) -> int:
        n = len(stations)
        total = sum(stations)
        lo = min(stations)                # lower bound (feasible)
        hi = total + k                    # upper bound (surely feasible or not)

        while lo + 1 < hi:
            mid = (lo + hi) // 2
            if self.check(stations, r, k, mid):
                lo = mid
            else:
                hi = mid

        # try the larger bound first
        if self.check(stations, r, k, hi):
            return hi
        return lo

    def check(self, stations: List[int], r: int, k: int, target: int) -> bool:
        n = len(stations)
        diff = [0] * n                     # extra power added to each station

        # initial window sum for i = 0 (indices 0 … min(r, n‑1))
        right = min(r, n - 1)
        cur = sum(stations[i] for i in range(right + 1))

        for i in range(n):
            if i > 0:
                # slide the window one step to the right
                if i + r < n:
                    cur += stations[i + r] + diff[i + r]
                if i - r - 1 >= 0:
                    cur -= stations[i - r - 1] + diff[i - r - 1]

            if cur < target:
                need = target - cur
                if need > k:
                    return False
                idx = min(i + r, n - 1)   # farthest station in the current window
                diff[idx] += need
                cur += need
                k -= need

        return True

