class Solution:
    def nextGreaterElement(self, nums1: List[int], nums2: List[int]) -> List[int]:
        result = []
        for num in nums1:
            # locate num in nums2
            try:
                idx = nums2.index(num)
            except ValueError:
                result.append(-1)
                continue
            # scan for the first greater element after idx
            nxt = -1
            for val in nums2[idx+1:]:
                if val > num:
                    nxt = val
                    break
            result.append(nxt)
        return result

