class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s) + 1

        from functools import lru_cache

        @lru_cache(None)
        def dfs(i: int, last: int) -> int:
            # i: number of processed characters (0 <= i <= len(s))
            # last: rank of the previous element among the i+1 placed numbers
            if i == len(s):
                # All characters processed; a valid permutation is formed
                return 1
            total = 0
            if s[i] == 'I':
                # next rank must be greater than last
                for cur in range(last + 1, i + 2):
                    total = (total + dfs(i + 1, cur)) % MOD
            else:  # 'D'
                # next rank must be <= last (allow equality because after removing previous number
                # the rank can stay the same)
                for cur in range(0, last + 1):
                    total = (total + dfs(i + 1, cur)) % MOD
            return total

        # The first element is the only one placed so its rank is 0
        return dfs(0, 0) % MOD

