from collections import defaultdict

class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        mem = defaultdict(int)

        def dfs(i: int, val: int) -> int:
            if i == n:
                return 1
            if (i, val) in mem:
                return mem[(i, val)]
            total = 0
            if s[i] == 'D':
                for new_val in range(val + 1):
                    total = (total + dfs(i + 1, new_val)) % MOD
            else:  # 'I'
                for new_val in range(val + 1, i + 2):
                    total = (total + dfs(i + 1, new_val)) % MOD
            mem[(i, val)] = total
            return total

        return dfs(0, 0)

