from typing import List
from functools import lru_cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        toppingCosts = toppingCosts * 2  # each topping can be used at most twice

        @lru_cache(maxsize=None)
        def dp(i: int, x: int) -> int:
            if x <= 0 or i >= len(toppingCosts):
                return 0
            # skip current topping (and its duplicate)
            skip = dp(i + 2, x)
            # take current topping
            take = toppingCosts[i] + dp(i + 1, x - toppingCosts[i])
            # choose the one closer to x, tie -> smaller sum
            return min(skip, take, key=lambda y: (abs(y - x), y))

        best = float('inf')
        for bc in baseCosts:
            cand = bc + dp(0, target - bc)
            if abs(cand - target) < abs(best - target) or (abs(cand - target) == abs(best - target) and cand < best):
                best = cand
        return best

class Solution:
    def smallestString(self, s: str) -> str:
        # If the string is all 'a', change the last character to 'z'.
        if s.count('a') == len(s):
            return s[:-1] + 'z'
        # Find the first non-'a' after any leading 'a's.
        i = 0
        n = len(s)
        while i < n and s[i] == 'a':
            i += 1
        # Decrement each character until the next 'a' or end of string.
        res = list(s)
        while i < n and s[i] != 'a':
            res[i] = chr(ord(s[i]) - 1)
