from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build a Trie of reversed forbidden words
        trie = {}
        for f in forbidden:
            node = trie
            for c in reversed(f):
                if c not in node:
                    node[c] = {}
                node = node[c]
            node['end'] = True

        max_len = 0
        left = 0  # earliest index that can start a valid substring

        for i in range(len(word)):
            node = trie
            # Scan backwards to find the rightmost forbidden suffix ending at i
            for j in range(i, -1, -1):
                c = word[j]
                if c not in node:
                    break
                node = node[c]
                if 'end' in node:
                    # Forbidden from j to i; move left boundary to j+1
                    left = max(left, j + 1)
                    # Once the rightmost (shortest) forbidden is found, stop scanning
                    break
            max_len = max(max_len, i - left + 1)

        return max_len

