from typing import List
from functools import lru_cache

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        self.R = len(pizza)
        self.C = len(pizza[0])
        # 2‑D prefix sum of apples
        self.ps = [[0] * (self.C + 1) for _ in range(self.R + 1)]
        for i in range(self.R):
            row_sum = 0
            for j in range(self.C):
                if pizza[i][j] == 'A':
                    row_sum += 1
                self.ps[i + 1][j + 1] = self.ps[i][j + 1] + row_sum

        # helper: apples in rectangle [r1, r2) x [c1, c2)
        def rectApple(r1: int, c1: int, r2: int, c2: int) -> int:
            return (self.ps[r2][c2] - self.ps[r1][c2] -
                    self.ps[r2][c1] + self.ps[r1][c1])

        @lru_cache(None)
        def dp(i: int, j: int, cuts: int) -> int:
            # no cuts left → final piece, must contain at least one apple
            if cuts == 0:
                return 1 if rectApple(i, j, self.R, self.C) > 0 else 0
            total = 0
            # try horizontal cuts
            for r in range(i + 1, self.R):
                if rectApple(i, j, r, self.C) > 0:
                    total += dp(r, j, cuts - 1)
            # try vertical cuts
            for c in range(j + 1, self.C):
                if rectApple(i, j, self.R, c) > 0:
                    total += dp(i, c, cuts - 1)
            return total % 1_000_000_007

        # need k‑1 cuts to obtain k pieces
        return dp(0, 0, k - 1) % 1_000_000_007

