class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        dp = [1]  # dp for length 1 (one element)
        for c in s:
            m = len(dp)
            new = [0] * (m + 1)
            # prefix sums of dp
            pref = [0] * (m + 1)
            for i in range(m):
                pref[i+1] = (pref[i] + dp[i]) % MOD
            total = pref[m]
            if c == 'I':
                # new[j] = sum_{k=0}^{j-1} dp[k]
                for j in range(1, m+1):
                    new[j] = pref[j]
            else:  # 'D'
                # new[j] = sum_{k=j}^{m-1} dp[k]
                for j in range(m):
                    new[j] = (total - pref[j]) % MOD
            dp = new
        return sum(dp) % MOD

