class Solution:
    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        from functools import lru_cache

        n = len(s)

        @lru_cache(None)
        def dp(i: int, prev: str, ct: int, k_rem: int) -> int:
            if k_rem < 0:
                return float('inf')
            if i == n:
                # encode the final run
                if ct > 1:
                    return len(str(ct)) + 1
                elif ct == 1:
                    return 1
                else:
                    return 0

            # delete current character
            delete = dp(i + 1, prev, ct, k_rem - 1)

            # keep current character
            if s[i] == prev:
                keep = dp(i + 1, prev, ct + 1, k_rem)
            else:
                # finish previous run
                if ct > 1:
                    add = len(str(ct)) + 1
                elif ct == 1:
                    add = 1
                else:
                    add = 0
                keep = add + dp(i + 1, s[i], 1, k_rem)

            return min(delete, keep)

        return dp(0, "", 0, k)

