class Solution:
    def findAllRecipes(self, recepies: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        from collections import defaultdict, deque

        graph = defaultdict(list)          # ingredient -> list of recipes that need it
        indegree = {}                      # recipe -> number of missing ingredients

        for i, recipe in enumerate(recepies):
            indegree[recipe] = len(ingredients[i])
            for ing in ingredients[i]:
                graph[ing].append(recipe)

        q = deque(supplies)                # start with all available supplies
        result = []

        while q:
            item = q.popleft()
            for recipe in graph[item]:
                indegree[recipe] -= 1
                if indegree[recipe] == 0:
                    result.append(recipe)
                    q.append(recipe)       # the produced recipe becomes a new supply

        return result

