from typing import List

class Solution:
    def restoreIpAddresses(self, s: str) -> List[str]:
        res = []
        cur = []
        n = len(s)

        def backtrack(start: int) -> None:
            # if we already have 4 segments, check if we've consumed the whole string
            if len(cur) == 4:
                if start == n:
                    res.append(".".join(cur))
                return

            # prune if too many digits remain to fit remaining segments
            if n - start > 3 * (4 - len(cur)):
                return
            if start >= n:
                return

            # leading zero can only be a single digit segment
            if s[start] == '0':
                cur.append('0')
                backtrack(start + 1)
                cur.pop()
                return

            # try segment lengths 1 to 3
            for length in range(1, 4):
                if start + length > n:
                    break
                segment = s[start:start + length]
                if int(segment) <= 255:
                    cur.append(segment)
                    backtrack(start + length)
                    cur.pop()

        backtrack(0)
        return res

