from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build a Trie of forbidden words
        trie = {}
        for f in forbidden:
            node = trie
            for ch in f:
                if ch not in node:
                    node[ch] = {}
                node = node[ch]
            node["end"] = True

        # Return length of the shortest forbidden word that starts at the beginning of s,
        # or False if none.
        def isForbidden(s: str):
            node = trie
            cnt = 0
            for ch in s:
                if ch not in node:
                    return False
                node = node[ch]
                cnt += 1
                if "end" in node:
                    return cnt
            return False

        res = 0
        j = len(word)  # exclusive right bound
        for i in range(len(word) - 1, -1, -1):
            # Check if any forbidden word starts at i within the current window
            length = isForbidden(word[i:j])
            if length:
                # shrink the right bound to exclude the full forbidden word
                j = min(j, i + length - 1)
            # update answer with the length of the valid substring starting at i
            if j > i:
                res = max(res, j - i)
        return res

