class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s) + 1
        from functools import lru_cache

        @lru_cache(None)
        def dp(i, j):
            if i == 0:
                return 1
            prev = s[i-1]
            total = 0
            if prev == 'I':
                for k in range(j):
                    total = (total + dp(i-1, k)) % MOD
            else:  # 'D'
                for k in range(j, i):
                    total = (total + dp(i-1, k)) % MOD
            return total

        ans = 0
        for j in range(n):
            ans = (ans + dp(n-1, j)) % MOD
        return ans

