from typing import List
from functools import lru_cache

class Solution:
    def ways(self, pizza: List[str], k: int) -> int:
        self.r = len(pizza)
        self.c = len(pizza[0])

        # 2D prefix sum of apples
        self.ps = [[0]*(self.c+1) for _ in range(self.r+1)]
        for i in range(self.r):
            row_sum = 0
            for j in range(self.c):
                row_sum += 1 if pizza[i][j] == 'A' else 0
                self.ps[i+1][j+1] = self.ps[i][j+1] + row_sum

        @lru_cache(None)
        def dfs(i: int, j: int, cuts: int) -> int:
            # if the remaining region contains no apple, no valid cut
            if self._apple(i, j, self.r - 1, self.c - 1) == 0:
                return 0
            if cuts == 0:
                return 1
            ans = 0
            # cut horizontally
            for row in range(i, self.r - 1):
                if self._apple(i, j, row, self.c - 1) > 0:
                    ans += dfs(row + 1, j, cuts - 1)
            # cut vertically
            for col in range(j, self.c - 1):
                if self._apple(i, j, self.r - 1, col) > 0:
                    ans += dfs(i, col + 1, cuts - 1)
            return ans

        return dfs(0, 0, k - 1) % (10**9 + 7)

    def _apple(self, r1: int, c1: int, r2: int, c2: int) -> int:
        return (self.ps[r2 + 1][c2 + 1] - self.ps[r1][c2 + 1] -
                self.ps[r2 + 1][c1] + self.ps[r1][c1])

