from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build a trie for all forbidden strings
        trie = {}
        for f in forbidden:
            node = trie
            for ch in f:
                if ch not in node:
                    node[ch] = {}
                node = node[ch]
            node['end'] = True

        # Returns the length of the longest forbidden suffix of word[i:j],
        # or False if there is none.
        def isForbidden(i: int, j: int):
            node = trie
            length = 0
            for idx in range(i, j):
                ch = word[idx]
                if ch not in node:
                    return False
                node = node[ch]
                length += 1
                if 'end' in node:
                    return length
            return False

        n = len(word)
        res = 0
        right = n  # exclusive bound: earliest index that cannot be part of a valid substring

        for i in range(n - 1, -1, -1):
            forbid_len = isForbidden(i, right)
            if forbid_len:
                # Move right to after the forbidden suffix
                right = min(right, i + forbid_len)
            # Length of the longest valid substring that starts at i
