class Solution:
    def dp(self, i, s, prev, k, ct, n, dct):
        if k < 0:
            return float('inf')
        if i == n:
            # finish the last run
            if ct > 1:
                return len(str(ct)) + 1
            elif ct == 1:
                return 1
            return 0
        if (i, prev, ct, k) in dct:
            return dct[(i, prev, ct, k)]

        # keep current character as part of the current run
        if s[i] == prev:
            inc = self.dp(i + 1, s, prev, k, ct + 1, n, dct)
        else:
            # close the previous run and start a new one
            if ct > 1:
                x = len(str(ct)) + 1
            elif ct == 1:
                x = 1
            else:
                x = 0
            inc = x + self.dp(i + 1, s, s[i], k, 1, n, dct)

        # delete current character (use one removal)
        exc = self.dp(i + 1, s, prev, k - 1, ct, n, dct)

        res = min(inc, exc)
        dct[(i, prev, ct, k)] = res
        return res

    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
