from typing import List
from functools import cache
import math

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        toppingCosts = toppingCosts * 2  # each topping can be used at most twice
        n = len(toppingCosts)

        @cache
        def dfs(i: int, x: int) -> int:
            # Base case: no remaining target or no more toppings
            if x < 0 or i >= n:
                return 0
            # Skip this topping (and its duplicate)
            skip = dfs(i + 2, x)
            # Take this topping
            take = toppingCosts[i] + dfs(i + 1, x - toppingCosts[i])
            # Choose the sum closest to x; tie‑break by smaller cost
            return min(skip, take, key=lambda y: (abs(y - x), y))

        ans = math.inf
        for bc in baseCosts:
            cand = bc + dfs(0, target - bc)
            if abs(cand - target) < abs(ans - target) or (abs(cand - target) == abs(ans - target) and cand < ans):
                ans = cand
        return ans

