from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build a trie, storing the length of each forbidden word at its terminal node.
        trie = {}
        max_len = 0
        for f in forbidden:
            t = trie
            max_len = max(max_len, len(f))
            for c in f:
                if c not in t:
                    t[c] = {}
                t = t[c]
            t["len"] = len(f)  # length of this forbidden word

        n = len(word)
        left = 0
        ans = 0

        # Slide a window [left, right] across the word.
        for right in range(n):
            t = trie
            # Only look at most max_len characters ahead to limit work.
            for i in range(right, min(n, right + max_len)):
                c = word[i]
                if c not in t:
                    break
                t = t[c]
                if "len" in t:
                    # A forbidden word of length t["len"] ends at i.
                    # Move left past its start (i - t["len"] + 2).
                    left = max(left, i - t["len"] + 2)
            # Current window is valid; update answer.
            ans = max(ans, right - left + 1)

        return ans

