class Solution:
    def findTheString(self, lcp: List[List[int]]) -> str:
        n = len(lcp)

        # validation
        for i in range(n):
            for j in range(i + 1, n):
                if lcp[i][j] != lcp[j][i]:
                    return ''
                if lcp[i][j] > n - j:
                    return ''
        for i in range(n):
            if lcp[i][i] != n - i:
                return ''

        # build pattern
        pattern = [None] * n
        next_char = 0
        for i in range(n):
            if pattern[i] is not None:
                continue
            pattern[i] = next_char
            next_char += 1
            for j in range(i + 1, n):
                if lcp[i][j] > 0:
                    if pattern[j] is not None and pattern[j] != pattern[i]:
                        return ''
                    pattern[j] = pattern[i]

        if None in pattern:
            return ''

        # compute LCP for the constructed pattern
        pattern_lcp = [[0] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            for j in range(n - 1, -1, -1):
                if pattern[i] == pattern[j]:
                    if max(i, j) + 1 < n:
                        pattern_lcp[i][j] = pattern_lcp[i + 1][j + 1] + 1
                    else:
                        pattern_lcp[i][j] = 1

        # compare with given LCP
        for i in range(n):
            for j in range(n):
                if lcp[i][j] != pattern_lcp[i][j]:
                    return ''

        # ensure at most 26 distinct letters
        if max(pattern) > 25:
            return ''

        return ''.join(chr(ord('a') + idx) for idx in pattern)

