from typing import List
from functools import cache
import math

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        # each topping can be used at most twice
        toppingCosts = toppingCosts * 2

        @cache
        def fn(i: int, x: int) -> int:
            """Return sum of a subsequence of toppingCosts[i:] closest to x."""
            # base: no more toppings or target already non‑positive
            if x <= 0 or i >= len(toppingCosts):
                return 0
            # skip current topping (and its duplicate)
            skip = fn(i + 2, x)
            # take current topping (may still take its duplicate later)
            take = toppingCosts[i] + fn(i + 1, x - toppingCosts[i])
            # choose the sum closest to x; if equal distance, pick larger sum
            if abs(skip - x) < abs(take - x):
                return skip
            elif abs(take - x) < abs(skip - x):
                return take
            else:
                return max(skip, take)

        best = math.inf
        for bc in baseCosts:
            total = bc + fn(0, target - bc)
            # keep the result with smallest distance to target, breaking ties by larger total
            if abs(total - target) < abs(best - target) or (abs(total - target) == abs(best - target) and total < best):
                best = total
        return best

