class Solution:
    def dp(self, i, prev, ct, k, s, n, memo):
        if k < 0:
            return float('inf')
        if i == n:
            # finish the current run
            if ct == 0:
                return 0
            if ct == 1:
                return 1
            return 1 + len(str(ct))
        if (i, prev, ct, k) in memo:
            return memo[(i, prev, ct, k)]

        # keep current character
        if s[i] == prev:
            keep = self.dp(i + 1, prev, ct + 1, k, s, n, memo)
        else:
            # cost of closing the previous run
            if ct == 1:
                cost_prev = 1
            elif ct > 1:
                cost_prev = 1 + len(str(ct))
            else:
                cost_prev = 0
            keep = cost_prev + self.dp(i + 1, s[i], 1, k, s, n, memo)

        # delete current character
        delete = self.dp(i + 1, prev, ct, k - 1, s, n, memo)

        ans = min(keep, delete)
        memo[(i, prev, ct, k)] = ans
        return ans

    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        n = len(s)
        return self.dp(0, '', 0, k, s, n, {})

