class Solution:
    def isPossibleToCutPath(self, grid: List[List[int]]) -> bool:
        if not grid:
            return False
        m, n = len(grid), len(grid[0])
        if grid[0][0] == 0 or grid[-1][-1] == 0:
            return False

        # Backward BFS from end (up/left) marking cells that can reach end.
        dq = deque([(m - 1, n - 1)])
        grid[m - 1][n - 1] = 2
        dirs_back = [(-1, 0), (0, -1)]

        while dq:
            i, j = dq.popleft()
            for di, dj in dirs_back:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 1:
                    grid[ni][nj] = 2
                    dq.append((ni, nj))

        # Forward BFS from start (down/right) only through cells marked 2.
        dq = deque([(0, 0)])
        grid[0][0] = 0
        dirs_fwd = [(1, 0), (0, 1)]

        while dq:
            i, j = dq.popleft()
            if i == m - 1 and j == n - 1:
                return True
            for di, dj in dirs_fwd:
                ni, nj = i + di, j + dj
                if 0 <= ni < m and 0 <= nj < n and grid[ni][nj] == 2:
                    grid[ni][nj] = 0
                    dq.append((ni, nj))

