class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        # If any character in s2 is not in s1, no match possible
        if not set(s2).issubset(set(s1)):
            return 0

        # Map from position in s2 to (s1 block count, s2 match count) after each s1 block
        pos = {}
        cnt1 = cnt2 = 0
        j = 0
        s2_len = len(s2)

        # Process s1 blocks until we either finish n1 blocks or detect a cycle
        while cnt1 < n1:
            for ch in s1:
                if ch == s2[j]:
                    j += 1
                    if j == s2_len:
                        cnt2 += 1
                        j = 0
            cnt1 += 1
            # If we've seen this j before, a cycle is found
            if j in pos:
                break
            pos[j] = (cnt1, cnt2)

        # If we processed all s1 blocks, simply return the number of s2 matches divided by n2
        if cnt1 == n1:
            return cnt2 // n2

        # Cycle detected: compute the contribution of full cycles and the remainder
        cnt1_start, cnt2_start = pos[j]
        cycle_s1 = cnt1 - cnt1_start          # number of s1 blocks in one cycle
        cycle_s2 = cnt2 - cnt2_start          # number of s2 matches in one cycle

        remaining = n1 - cnt1_start            # remaining s1 blocks after the cycle start
        total = cnt2_start + (remaining // cycle_s1) * cycle_s2

        # Simulate the remaining partial cycle to count extra s2 matches
        k = j                                   # index in s2 at the start of the cycle
        extra = 0
        for _ in range(remaining % cycle_s1):
            for ch in s1:
                if ch == s2[k]:
                    k += 1
                    if k == s2_len:
                        extra += 1
                        k = 0
        total += extra

        return total // n2

