from typing import List
from functools import cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        toppingCosts *= 2  # allow each topping up to twice

        @cache
        def dfs(i: int, remain: int) -> int:
            """Return the sum of a subsequence of toppingCosts[i:] closest to remain."""
            if remain <= 0 or i == len(toppingCosts):
                return 0
            # Skip this topping
            skip = dfs(i + 1, remain)
            # Take this topping
            take = toppingCosts[i] + dfs(i + 1, remain - toppingCosts[i])
            # Choose the one closer to remain; tie-break with smaller sum
            if abs(skip - remain) < abs(take - remain):
                return skip
            elif abs(take - remain) < abs(skip - remain):
                return take
            else:
                return min(skip, take)

        best = float('inf')
        for bc in baseCosts:
            total = bc + dfs(0, target - bc)
            # Compare using the same closeness criteria
            if abs(total - target) < abs(best - target) or (abs(total - target) == abs(best - target) and total < best):
                best = total
        return best

