from functools import cache

class Solution:
    def closestCost(self, baseCosts: List[int], toppingCosts: List[int], target: int) -> int:
        toppingCosts *= 2  # allow each topping to be used at most twice

        @cache
        def fn(i: int, x: int) -> int:
            """Return sum of a subsequence of toppingCosts[i:] closest to x."""
            if x <= 0 or i == len(toppingCosts):
                return 0
            # skip this topping
            skip = fn(i + 1, x)
            # take this topping (once)
            take = toppingCosts[i] + fn(i + 2, x - toppingCosts[i])
            # choose the one with smallest distance to x, break ties by smaller sum
            return min(skip, take, key=lambda y: (abs(y - x), y))

        ans = math.inf
        for bc in baseCosts:
            total = bc + fn(0, target - bc)
            # keep the total closest to target, break ties by smaller cost
