class Solution:
    def getMaxRepetitions(self, s1: str, n1: int, s2: str, n2: int) -> int:
        if n1 == 0:
            return 0
        if not set(s2).issubset(set(s1)):
            return 0

        s1_cnt = 0       # number of s1 repetitions consumed
        s2_cnt = 0       # number of completed s2
        i = 0            # current index in s1

        # map from index in s1 to (s1_cnt, s2_cnt) after a full s2
        rec = {}

        while True:
            # match one whole s2
            for ch in s2:
                pos = s1.find(ch, i)
                if pos == -1:
                    # need another s1 block
                    s1_cnt += 1
                    if s1_cnt == n1:
                        return s2_cnt // n2
                    i = 0
                    pos = s1.find(ch)
                i = pos + 1

            s2_cnt += 1
            if s1_cnt == n1:
                return s2_cnt // n2

            # cycle detection
            if i in rec:
                pre_s1, pre_s2 = rec[i]
                in_s1 = s1_cnt - pre_s1
                in_s2 = s2_cnt - pre_s2
                remain = n1 - pre_s1
                cycles = remain // in_s1
                total_s2 = pre_s2 + cycles * in_s2
                rest = remain % in_s1

                # simulate the remaining repetitions
                s1_cnt = pre_s1
                s2_cnt = total_s2
                for _ in range(rest):
                    for ch in s2:
                        pos = s1.find(ch, i)
                        if pos == -1:
                            s1_cnt += 1
                            if s1_cnt == n1:
                                break
                            i = 0
                            pos = s1.find(ch)
                        i = pos + 1
                    if s1_cnt == n1:
                        break
                    s2_cnt += 1
                return s2_cnt // n2
            else:
                rec[i] = (s1_cnt, s2_cnt)

