class Solution:
    def numPermsDISequence(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        # dp[j] – number of ways for the prefix of length i+1 whose last element has rank j.
        dp = [1] + [0] * n
        for i, ch in enumerate(s):
            m = i + 1          # current length of dp
            ndp = [0] * (m + 1)
            if ch == 'I':
                # increasing: next rank must be greater -> prefix sums
                running = 0
                for j in range(m + 1):
                    if j:
                        running = (running + dp[j - 1]) % MOD
                    ndp[j] = running
            else:  # 'D'
                # decreasing: next rank must be smaller or equal -> suffix sums
                running = 0
                for j in range(m, -1, -1):
                    if j < m:
                        running = (running + dp[j]) % MOD
                    ndp[j] = running
            dp = ndp
        return sum(dp) % MOD

