from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build trie of forbidden words
        trie = {}
        for f in forbidden:
            node = trie
            for ch in f:
                if ch not in node:
                    node[ch] = {}
                node = node[ch]
            node['end'] = True

        # Return length of the first forbidden prefix in s, or False if none
        def first_forbidden(s: str):
            node = trie
            length = 0
            for ch in s:
                if ch not in node:
                    return False
                node = node[ch]
                length += 1
                if 'end' in node:
                    return length
            return False

        n = len(word)
        j = n
        ans = 0
        for i in range(n - 1, -1, -1):
            matched = first_forbidden(word[i:j])
            if matched:
                # shrink right bound to exclude the matched forbidden prefix
                j = min(j, i + matched)
            ans = max(ans, j - i)
        return ans

