from typing import List

class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        # Build a trie of reversed forbidden strings.
        trie = {}
        for f in forbidden:
            node = trie
            for c in reversed(f):
                if c not in node:
                    node[c] = {}
                node = node[c]
            node['end'] = True

        n = len(word)
        left = 0
        ans = 0

        for i in range(n):
            node = trie
            # Scan backwards from i to left to find any forbidden ending at i.
            for j in range(i, left - 1, -1):
                c = word[j]
                if c not in node:
                    break
                node = node[c]
                if node.get('end'):
                    # A forbidden ends at i, move left beyond its end.
                    left = i + 1
                    # Once left reaches i+1, no longer need to check further.
                    break
            # Update answer with the length of the longest valid substring ending at i.
            ans = max(ans, i - left + 1)

        return ans

