class Solution:
    def dp(self, i, s, prev, run, k, n, memo):
        if k < 0:
            return float('inf')
        if i == n:
            # cost for the final run
            if run > 1:
                return len(str(run)) + 1
            elif run == 1:
                return 1
            else:
                return 0
        if (i, prev, run, k) in memo:
            return memo[(i, prev, run, k)]
        if s[i] == prev:
            keep = self.dp(i+1, s, prev, run+1, k, n, memo)
            delete = self.dp(i+1, s, prev, run, k-1, n, memo)
            res = min(keep, delete)
        else:
            # close previous run
            if run > 1:
                cost = len(str(run)) + 1
            elif run == 1:
                cost = 1
            else:
                cost = 0
            keep = cost + self.dp(i+1, s, s[i], 1, k, n, memo)
            delete = self.dp(i+1, s, prev, run, k-1, n, memo)
            res = min(keep, delete)
        memo[(i, prev, run, k)] = res
        return res

    def getLengthOfOptimalCompression(self, s: str, k: int) -> int:
        n = len(s)
        return self.dp(0, s, "", 0, k, n, {})

