import sys
from typing import List

class Solution:
    def componentValue(self, nums: List[int], edges: List[List[int]]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # build adjacency list
        tree = [[] for _ in range(n)]
        for u, v in edges:
            tree[u].append(v)
            tree[v].append(u)

        total = sum(nums)
        max_val = max(nums)

        # collect all divisors of total
        divisors = []
        i = 1
        while i * i <= total:
            if total % i == 0:
                divisors.append(i)
                if i != total // i:
                    divisors.append(total // i)
            i += 1
        divisors.sort()

        sys.setrecursionlimit(10**6)

        # try each possible component sum (divisor) from small to large
        for cand in divisors:
            if cand < max_val:          # a node is larger than cand -> impossible
                continue

            # post‑order DFS that returns subtree sum modulo cand
            def dfs(u: int, parent: int) -> int:
                s = nums[u]
                for v in tree[u]:
                    if v != parent:
                        s += dfs(v, u)
                return s % cand

            if dfs(0, -1) == 0:
                # valid partition: total//cand components, remove (components‑1) edges
                return total // cand - 1

        return 0
